// n8n Code node: "Build ticket query" (mode: Run Once for All Items)
// Works out the analysis window and builds the Autotask REST query body.
// Two windows are fetched (current + previous period of the same length)
// so that ticket volume trends can be compared.

const config = $('Config').first().json;

const lookbackDays = Number(config.lookbackDays) || 30;
const now = config.referenceDate ? new Date(config.referenceDate) : new Date();
if (Number.isNaN(now.getTime())) {
  throw new Error(`Config.referenceDate is not a valid date: ${config.referenceDate}`);
}

const DAY_MS = 24 * 60 * 60 * 1000;
const currentStart = new Date(now.getTime() - lookbackDays * DAY_MS);
const previousStart = new Date(now.getTime() - 2 * lookbackDays * DAY_MS);

// Autotask REST API query: POST /Tickets/query
// Only the fields the analysis needs are requested (data minimisation).
const queryBody = {
  MaxRecords: Number(config.maxTickets) || 500,
  IncludeFields: [
    'id', 'ticketNumber', 'title', 'description', 'companyID',
    'createDate', 'completedDate', 'status', 'priority',
    'issueType', 'subIssueType', 'queueID',
  ],
  filter: [
    { op: 'gte', field: 'createDate', value: previousStart.toISOString() },
  ],
};

return [{
  json: {
    queryBody,
    now: now.toISOString(),
    currentStart: currentStart.toISOString(),
    previousStart: previousStart.toISOString(),
    lookbackDays,
  },
}];

// n8n Code node: "Build company query" (mode: Run Once for All Items)
// Collects the distinct company IDs from the ticket query so their names
// can be looked up in one request.

const response = $input.first().json;
const tickets = Array.isArray(response.items) ? response.items : [];

if (response.pageDetails && response.pageDetails.nextPageUrl) {
  // The template reads one page (Config.maxTickets, max 500 per Autotask page).
  // See the README roadmap for pagination support.
  console.log('Autotask returned more tickets than one page; only the first page is analysed.');
}

const companyIds = [...new Set(tickets.map((t) => t.companyID).filter((id) => id !== null && id !== undefined))];

return [{
  json: {
    ticketCount: tickets.length,
    companyIds,
    queryBody: {
      IncludeFields: ['id', 'companyName'],
      filter: [{ op: 'in', field: 'id', value: companyIds.length ? companyIds : [0] }],
    },
  },
}];

// n8n Code node: "Clean & group by client" (mode: Run Once for All Items)
// 1. Cleans ticket text (strips HTML, redacts emails / phone numbers / IPs, truncates).
// 2. Groups tickets by client and splits them into the current and previous period.
// 3. Computes deterministic statistics used by the prompt and the risk index.
// Outputs one item per client that has at least Config.minTicketsPerClient tickets.

const config = $('Config').first().json;
const windowInfo = $('Build ticket query').first().json;
const tickets = $('Autotask: query tickets').first().json.items || [];
const companies = $('Autotask: query companies').first().json.items || [];

const minTickets = Number(config.minTicketsPerClient) || 3;
const agingDays = Number(config.agingDays) || 14;
const highPriorityValues = String(config.highPriorityValues || '1,4')
  .split(',').map((v) => Number(v.trim())).filter((v) => !Number.isNaN(v));
const DAY_MS = 24 * 60 * 60 * 1000;

const now = new Date(windowInfo.now);
const currentStart = new Date(windowInfo.currentStart);

const companyNames = new Map(companies.map((c) => [c.id, c.companyName]));

function cleanText(value, maxLength) {
  if (!value) return '';
  return String(value)
    .replace(/<[^>]*>/g, ' ')                                   // HTML tags
    .replace(/&nbsp;|&amp;|&lt;|&gt;|&quot;|&#39;/g, ' ')        // common entities
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[email]') // email addresses
    .replace(/\+?\d[\d\s().-]{7,}\d/g, '[phone]')                // phone-like numbers
    .replace(/\b\d{1,3}(?:\.\d{1,3}){3}\b/g, '[ip]')             // IPv4 addresses
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, maxLength);
}

const byClient = new Map();
for (const t of tickets) {
  const key = t.companyID;
  if (!byClient.has(key)) byClient.set(key, []);
  byClient.get(key).push(t);
}

const results = [];
for (const [companyId, clientTickets] of byClient) {
  const current = clientTickets.filter((t) => new Date(t.createDate) >= currentStart);
  const previous = clientTickets.filter((t) => new Date(t.createDate) < currentStart);
  if (current.length < minTickets) continue;

  // Category = issueType/subIssueType pair. Picklist IDs differ per Autotask
  // instance, so IDs are used as-is; map them to labels if you need readable output.
  const categoryCounts = {};
  for (const t of current) {
    const category = `${t.issueType ?? 'none'}/${t.subIssueType ?? 'none'}`;
    categoryCounts[category] = (categoryCounts[category] || 0) + 1;
  }
  const recurringCategoryTickets = Object.values(categoryCounts)
    .filter((n) => n >= 3)
    .reduce((sum, n) => sum + n, 0);

  const highPriority = current.filter((t) => highPriorityValues.includes(Number(t.priority))).length;
  const agingOpen = current.filter((t) => !t.completedDate
    && (now.getTime() - new Date(t.createDate).getTime()) / DAY_MS > agingDays).length;

  results.push({
    json: {
      companyId,
      clientName: companyNames.get(companyId) || `Company ${companyId}`,
      periodStart: windowInfo.currentStart.slice(0, 10),
      periodEnd: windowInfo.now.slice(0, 10),
      stats: {
        currentTickets: current.length,
        previousTickets: previous.length,
        highPriorityTickets: highPriority,
        openOlderThanAgingDays: agingOpen,
        agingDays,
        recurringCategoryTickets,
        categoryCounts,
      },
      tickets: current.map((t) => ({
        ticketNumber: t.ticketNumber,
        created: t.createDate,
        completed: t.completedDate || null,
        priority: t.priority,
        category: `${t.issueType ?? 'none'}/${t.subIssueType ?? 'none'}`,
        title: cleanText(t.title, 200),
        description: cleanText(t.description, 1000),
      })),
    },
  });
}

return results;

// n8n Code node: "Build Claude request" (mode: Run Once for All Items)
// Fills the prompt templates (from prompts/ in the repository, embedded at build
// time by scripts/build-workflow.mjs) and builds an Anthropic Messages API body
// for each client.

const config = $('Config').first().json;

const SYSTEM_PROMPT = "You are a senior MSP service analyst. You review IT support tickets for one client of a managed service provider and produce structured, factual documentation for the service team.\n\nRules:\n- Base every statement only on the tickets and statistics provided. Do not invent systems, users, incidents or numbers.\n- Group tickets that describe the same underlying problem into one recurring issue, even if the wording differs.\n- A recurring issue needs at least 2 tickets. Reference the ticket numbers that support it.\n- Separate likely root causes from symptoms. If the root cause is unclear, say so and propose how to confirm it.\n- Flag security weaknesses and vulnerabilities only when the tickets show evidence of them (for example phishing reports, missing patches, failed backups, end-of-life systems, disabled MFA, excessive admin rights). Rate each as low, medium or high.\n- Remediation steps must be concrete and actionable by an MSP technician.\n- Proactive opportunities are improvements or services that would prevent the recurring issues. Keep them practical and avoid sales language.\n- Ticket text has already been redacted. Never try to reconstruct removed personal data.\n- Respond with a single JSON object that matches the schema you are given. No markdown fences and no text outside the JSON.";
const USER_PROMPT_TEMPLATE = "Analyse the support tickets below for client \"{{CLIENT_NAME}}\".\n\nAnalysis period: {{PERIOD_START}} to {{PERIOD_END}}\n\nPre-computed ticket statistics (deterministic, from the PSA data):\n{{TICKET_STATS_JSON}}\n\nTickets in the analysis period (JSON array, text already cleaned and redacted):\n{{TICKETS_JSON}}\n\nReturn a JSON object that matches this schema exactly:\n{{OUTPUT_SCHEMA_JSON}}";
const OUTPUT_SCHEMA = {"client_summary":"string - 3 to 5 sentences: overall support picture for the period","recurring_issues":[{"title":"string - short name of the recurring problem","ticket_count":"integer - number of tickets in this cluster","ticket_numbers":["string - ticket numbers that belong to this cluster"],"category":"string - one of: backup, endpoint, network, identity, email, security, application, hardware, other","likely_root_cause":"string - most likely underlying cause, or 'unclear' with how to confirm","remediation":["string - concrete step"]}],"vulnerabilities":[{"title":"string","severity":"string - low | medium | high","evidence_ticket_numbers":["string"],"recommendation":"string"}],"proactive_opportunities":["string - preventive improvement or service suggestion"],"documentation_notes":["string - facts worth adding to the client's documentation (environment, recurring procedures, known issues)"]};

function fill(template, values) {
  return Object.entries(values).reduce(
    (text, [key, value]) => text.split(`{{${key}}}`).join(value),
    template,
  );
}

return $input.all().map((item) => {
  const c = item.json;
  const userPrompt = fill(USER_PROMPT_TEMPLATE, {
    CLIENT_NAME: c.clientName,
    PERIOD_START: c.periodStart,
    PERIOD_END: c.periodEnd,
    TICKET_STATS_JSON: JSON.stringify(c.stats, null, 2),
    TICKETS_JSON: JSON.stringify(c.tickets, null, 2),
    OUTPUT_SCHEMA_JSON: JSON.stringify(OUTPUT_SCHEMA, null, 2),
  });

  return {
    json: {
      companyId: c.companyId,
      clientName: c.clientName,
      requestBody: {
        model: config.claudeModel,
        max_tokens: Number(config.maxTokens) || 4000,
        temperature: 0.2,
        system: SYSTEM_PROMPT,
        messages: [{ role: 'user', content: userPrompt }],
      },
    },
  };
});

// n8n Code node: "Parse analysis & score risk index" (mode: Run Once for All Items)
// Parses Claude's JSON answer for each client and calculates the growth/risk
// index described in docs/risk-index.md. Items arrive in the same order as the
// "Clean & group by client" output (one Claude call per client).

const clients = $('Clean & group by client').all();

// Weights must add up to 100. See docs/risk-index.md before changing them.
const WEIGHTS = { volumeTrend: 20, recurrence: 25, severity: 20, security: 25, backlog: 10 };
const SEVERITY_POINTS = { low: 1, medium: 2, high: 3 };

const clamp01 = (n) => Math.max(0, Math.min(1, n));
const round2 = (n) => Math.round(n * 100) / 100;

function parseClaudeResponse(body) {
  const text = (body.content || [])
    .filter((part) => part.type === 'text')
    .map((part) => part.text)
    .join('')
    .trim()
    .replace(/^```(?:json)?\s*/i, '')   // tolerate accidental code fences
    .replace(/\s*```$/, '');
  try {
    return { analysis: JSON.parse(text), parseError: null };
  } catch (error) {
    return { analysis: null, parseError: `Could not parse model output as JSON: ${error.message}` };
  }
}

function band(score) {
  if (score >= 75) return 'High';
  if (score >= 50) return 'Elevated';
  if (score >= 25) return 'Moderate';
  return 'Low';
}

return $input.all().map((item, index) => {
  const client = clients[index].json;
  const s = client.stats;
  const { analysis, parseError } = parseClaudeResponse(item.json);

  const recurringIssues = analysis?.recurring_issues || [];
  const vulnerabilities = analysis?.vulnerabilities || [];

  // 1. Volume trend: full score when volume doubles versus the previous period.
  const trendRatio = s.currentTickets / Math.max(s.previousTickets, 1);
  const volumeTrend = clamp01(trendRatio - 1);

  // 2. Recurrence: share of tickets in recurring clusters (AI clusters or
  //    deterministic category repeats, whichever is higher).
  const aiRecurring = Math.min(
    recurringIssues.reduce((sum, r) => sum + (Number(r.ticket_count) || 0), 0),
    s.currentTickets,
  );
  const recurrence = clamp01(Math.max(aiRecurring, s.recurringCategoryTickets) / s.currentTickets);

  // 3. Severity: share of high/critical priority tickets.
  const severity = clamp01(s.highPriorityTickets / s.currentTickets);

  // 4. Security: weighted vulnerability points; 6 points (e.g. two high) = full score.
  const securityPoints = vulnerabilities.reduce(
    (sum, v) => sum + (SEVERITY_POINTS[String(v.severity).toLowerCase()] || 0), 0);
  const security = clamp01(securityPoints / 6);

  // 5. Backlog: share of tickets still open after the aging threshold; 50% = full score.
  const backlog = clamp01((s.openOlderThanAgingDays / s.currentTickets) * 2);

  const components = { volumeTrend, recurrence, severity, security, backlog };
  const riskIndex = Math.round(
    Object.entries(WEIGHTS).reduce((sum, [key, weight]) => sum + weight * components[key], 0),
  );

  return {
    json: {
      companyId: client.companyId,
      clientName: client.clientName,
      periodStart: client.periodStart,
      periodEnd: client.periodEnd,
      stats: s,
      riskIndex,
      riskBand: band(riskIndex),
      confidence: s.currentTickets >= 10 ? 'normal' : 'low (fewer than 10 tickets)',
      components: Object.fromEntries(Object.entries(components).map(([k, v]) => [k, round2(v)])),
      analysis,
      parseError,
    },
  };
});

// n8n Code node: "Build client documentation" (mode: Run Once for All Items)
// Turns each scored analysis into client-ready Markdown, and adds one portfolio
// summary item sorted by risk index.

const list = (values) => (values && values.length ? values.map((v) => `- ${v}`).join('\n') : '- None identified');

const reports = $input.all().map((item) => {
  const r = item.json;
  const a = r.analysis || {};
  const lines = [];

  lines.push(`# Support review: ${r.clientName}`);
  lines.push('');
  lines.push(`Period: ${r.periodStart} to ${r.periodEnd}  `);
  lines.push(`Growth/risk index: **${r.riskIndex} (${r.riskBand})**, confidence: ${r.confidence}`);
  lines.push('');

  if (r.parseError) {
    lines.push(`> Analysis unavailable: ${r.parseError}`);
    lines.push('');
  }

  lines.push('## Summary', '', a.client_summary || 'No summary available.', '');

  lines.push('## Ticket statistics', '');
  lines.push('| Metric | Value |', '|---|---|');
  lines.push(`| Tickets this period | ${r.stats.currentTickets} |`);
  lines.push(`| Tickets previous period | ${r.stats.previousTickets} |`);
  lines.push(`| High/critical priority | ${r.stats.highPriorityTickets} |`);
  lines.push(`| Open longer than ${r.stats.agingDays} days | ${r.stats.openOlderThanAgingDays} |`);
  lines.push('');

  lines.push('## Recurring issues', '');
  const issues = a.recurring_issues || [];
  if (!issues.length) lines.push('No recurring issues identified.', '');
  for (const issue of issues) {
    lines.push(`### ${issue.title} (${issue.ticket_count} tickets, ${issue.category})`, '');
    lines.push(`Tickets: ${(issue.ticket_numbers || []).join(', ')}  `);
    lines.push(`Likely root cause: ${issue.likely_root_cause}`, '');
    lines.push('Remediation:', '', list(issue.remediation), '');
  }

  lines.push('## Vulnerabilities and risks', '');
  const vulns = a.vulnerabilities || [];
  if (!vulns.length) {
    lines.push('None identified from ticket evidence.', '');
  } else {
    lines.push('| Severity | Finding | Evidence | Recommendation |', '|---|---|---|---|');
    for (const v of vulns) {
      lines.push(`| ${v.severity} | ${v.title} | ${(v.evidence_ticket_numbers || []).join(', ')} | ${v.recommendation} |`);
    }
    lines.push('');
  }

  lines.push('## Proactive opportunities', '', list(a.proactive_opportunities), '');
  lines.push('## Documentation notes', '', list(a.documentation_notes), '');

  lines.push('## Risk index breakdown', '');
  lines.push('| Component | Score (0-1) |', '|---|---|');
  for (const [k, v] of Object.entries(r.components)) lines.push(`| ${k} | ${v} |`);
  lines.push('');
  lines.push('_Generated automatically from PSA ticket data. Review before sharing with the client._');

  return {
    json: {
      type: 'client-report',
      companyId: r.companyId,
      clientName: r.clientName,
      riskIndex: r.riskIndex,
      riskBand: r.riskBand,
      recurringIssueCount: issues.length,
      vulnerabilityCount: vulns.length,
      markdown: `${lines.join('\n')}\n`,
    },
  };
});

const summary = {
  json: {
    type: 'portfolio-summary',
    generatedAt: new Date().toISOString(),
    clients: reports
      .map((r) => ({
        clientName: r.json.clientName,
        riskIndex: r.json.riskIndex,
        riskBand: r.json.riskBand,
        recurringIssues: r.json.recurringIssueCount,
        vulnerabilities: r.json.vulnerabilityCount,
      }))
      .sort((x, y) => y.riskIndex - x.riskIndex),
  },
};

return [...reports, summary];
